def countQuadruples(firstString: str, secondString: str) -> int:
    # First index of each character in firstString
    first_idx = {}
    for idx, c in enumerate(firstString):
        if c not in first_idx:
            first_idx[c] = idx

    # Last index of each character in secondString
    last_idx = {}
    for idx, c in enumerate(secondString):
        last_idx[c] = idx

    min_diff = float('inf')
    count = 0

    # For each character occurring in both strings, the best pair is
    # (first index in firstString, last index in secondString)
    for c, i in first_idx.items():
        if c in last_idx:
            diff = i - last_idx[c]
            if diff < min_diff:
                min_diff = diff
                count = 1
            elif diff == min_diff:
                count += 1

    return count
